     1	/** Settings dashboard protocol shared by the extension and settings webview. */
     2	
     3	export interface BundledResourceRow {
     4		id: "custom-footer" | "filechanges" | "nebula-pulse";
     5		label: string;
     6		kind: "extension" | "theme";
     7		enabled: boolean;
     8		enabledByDefault: boolean;
     9	}
    10	
    11	export interface PackageStatusEntry {
    12		source: string;
    13		scope: "user" | "project";
    14		installed: boolean;
    15	}
    16	
    17	export interface DashboardData {
    18		agentDir: string;
    19		sessionDir: string;
    20		bundledResources: BundledResourceRow[];
    21		packages: {
    22			configured: number;
    23			installed: number;
    24			missing: number;
    25			entries: PackageStatusEntry[];
    26		};
    27		files: {
    28			settings: { path: string; exists: boolean };
    29			models: { path: string; exists: boolean };
    30			auth: { path: string; exists: boolean };
    31		};
    32	}
    33	
    34	export type SettingsMessage =
    35		| { command: "settings:get" }
    36		| {
    37				command: "settings:setBundledResource";
    38				id: BundledResourceRow["id"];
    39				enabled: boolean;
    40		  }
    41		| { command: "settings:openFile"; file: "settings" | "models" | "auth" }
    42		| { command: "settings:refresh" }
    43		| { command: "settings:openSessions" };
    44	
    45	export type SettingsReply =
    46		| { command: "settings:data"; data: DashboardData }
    47		| { command: "settings:saved"; ok: true; resource: BundledResourceRow["id"] }
    48		| {
    49				command: "settings:opened";
    50				file: "settings" | "models" | "auth";
    51				path: string;
    52		  }
    53		| { command: "settings:error"; message: string };

