   102			const packageManager = new sdk.DefaultPackageManager({
   103				cwd,
   104				agentDir: this.agentDir,
   105				settingsManager,
   106			});
   107			const packages: PackageStatusEntry[] = packageManager
   108				.listConfiguredPackages()
   109				.map((entry) => ({
