   131			}
   132			const settings = readJsonFile<Record<string, unknown>>(settingsPath) ?? {};
   133			const current = readBundledResourceConfig(settings);
   134			const next: BundledResourceConfig = {
   135				bundledExtensions: { ...current.bundledExtensions },
   136				bundledThemes: { ...current.bundledThemes },
