    78					case "settings:openSessions":
    79						await vscode.commands.executeCommand("codepi.openSessionsTab");
    80						break;
    81				}
    82			} catch (err) {
    83				this.post({
    84					command: "settings:error",
    85					message: err instanceof Error ? err.message : String(err),
    86				});
    87			}
    88		}
    89	
    90		private post(msg: SettingsReply): void {
    91			this.view?.webview.postMessage(msg);
    92		}
    93	
    94		private async sendData(): Promise<void> {
    95			const settingsPath = getSettingsPathForAgent(this.agentDir);
    96			const settings = readJsonFile<Record<string, unknown>>(settingsPath) ?? {};
    97			const sdk = await getSdk();
    98			const cwd =
    99				vscode.workspace.workspaceFolders?.[0]?.uri.fsPath ?? this.agentDir;
   100			const settingsManager = sdk.SettingsManager.create(cwd, this.agentDir);
   101			const packageManager = new sdk.DefaultPackageManager({
   102				cwd,
   103				agentDir: this.agentDir,
   104				settingsManager,
   105			});
   106			const packages: PackageStatusEntry[] = packageManager
   107				.listConfiguredPackages()
   108				.map((entry) => ({
   109					source: entry.source,
   110					scope: entry.scope,
   111					installed: entry.installedPath !== undefined,
   112				}));
   113			const data = buildDashboardData(
   114				this.agentDir,
   115				this.sessionDir,
   116				settings,
   117				packages,
   118				getDashboardFileStatus(this.agentDir),
   119			);
   120			this.post({ command: "settings:data", data });
   121		}
   122	
   123		private async setBundledResource(
   124			id: DashboardData["bundledResources"][number]["id"],
   125			enabled: boolean,
   126		): Promise<void> {
   127			const settingsPath = getSettingsPathForAgent(this.agentDir);
   128			const settings = readJsonFile<Record<string, unknown>>(settingsPath) ?? {};
   129			const current = readBundledResourceConfig(settings);
   130			const next: BundledResourceConfig = {
   131				bundledExtensions: { ...current.bundledExtensions },
   132				bundledThemes: { ...current.bundledThemes },
   133			};
   134			if (id === "nebula-pulse") next.bundledThemes["nebula-pulse"] = enabled;
   135			else next.bundledExtensions[id] = enabled;
   136			updateBundledResourceConfig(settingsPath, next);
   137			this.onConfigSaved();
   138			this.post({ command: "settings:saved", ok: true, resource: id });
   139			await this.sendData();
   140		}
   141	
   142		private async openFile(file: "settings" | "models" | "auth"): Promise<void> {
   143			const filePath = ensurePiJsonFileInDir(this.agentDir, file);
   144			const document = await vscode.workspace.openTextDocument(
   145				vscode.Uri.file(filePath),
   146			);
   147			await vscode.window.showTextDocument(document, { preview: false });
   148			this.post({ command: "settings:opened", file, path: filePath });
   149		}
   150	}
   151	
   152	function getSettingsPathForAgent(agentDir: string): string {
   153		return `${agentDir}/settings.json`;
   154	}
   155	
   156	function buildSettingsHtml(
   157		extensionUri: vscode.Uri,
   158		webview: vscode.Webview,
   159	): string {
   160		const distUri = vscode.Uri.joinPath(extensionUri, "webview-ui", "dist");
   161		const scriptUri = webview.asWebviewUri(
   162			vscode.Uri.joinPath(distUri, "assets", "settings.js"),
   163		);
   164		const styleUri = webview.asWebviewUri(
   165			vscode.Uri.joinPath(distUri, "assets", "index.css"),
   166		);
   167		const nonce = getNonce();
   168		return /* html */ `<!DOCTYPE html>
   169	<html lang="en">
   170	<head>
   171	  <meta charset="UTF-8" />
   172	  <meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src ${webview.cspSource} 'unsafe-inline'; script-src ${webview.cspSource} 'nonce-${nonce}';" />
   173	  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
   174	  <link rel="stylesheet" crossorigin href="${styleUri}" />
   175	  <title>CodePi Settings</title>
   176	</head>
   177	<body>
   178	  <div id="root"></div>
   179	  <script type="module" crossorigin nonce="${nonce}" src="${scriptUri}"></script>
   180	</body>
   181	</html>`;
   182	}
   183	
   184	function getNonce(): string {
   185		let text = "";
   186		const possible =
   187			"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
   188		for (let i = 0; i < 32; i++)
   189			text += possible.charAt(Math.floor(Math.random() * possible.length));
   190		return text;

